#!/usr/bin/env node
'use strict';
/*
 * fixture-server.js -- deterministic HTTP range/resume test fixture.
 *
 * Owner: env-runner. NO npm dependencies. Node >= 18.
 *
 * Purpose: give the Electron (ground truth) and the Android port the SAME
 * byte stream so their download results can be compared by SHA-256.
 *
 * ---------------------------------------------------------------------------
 * DETERMINISTIC BYTE STREAM (must be reimplemented identically in Kotlin)
 * ---------------------------------------------------------------------------
 * Each file has its own content buffer generated by the same 32-bit
 * xorshift PRNG seeded from the file name:
 *
 *   seed(name) = (BASE_SEED ^ fnv1a32(name)) >>> 0
 *   fnv1a32(s): h = 2166136261
 *               for each byte b of s: h = ((h ^ b) * 16777619) mod 2^32
 *
 *   x = seed(name)                       (unsigned 32-bit)
 *   for i in 0..length-1:
 *       x ^= (x << 13)  (mod 2^32)
 *       x ^= (x >>> 17) (logical right shift)
 *       x ^= (x << 5)   (mod 2^32)
 *       byte[i] = x & 0xFF
 *
 * In Kotlin/Java: keep x as Int and use xor/shl/ushr; the low 8 bits are
 * identical to the unsigned-32 arithmetic above. Hash the result with SHA-256.
 *
 * ---------------------------------------------------------------------------
 * ENDPOINTS
 * ---------------------------------------------------------------------------
 *  GET /health              -> JSON metadata (sizes, seed, partial size)
 *  GET /file/plain.bin      -> 8388608 bytes, supports Range (206 + Content-Range)
 *  GET /file/norange.bin    -> 8388608 bytes, ALWAYS ignores Range (200 full body)
 *  GET /file/flaky.bin      -> 8388608 bytes, supports Range; the FIRST request
 *                              is cut after FLAKY_CUT bytes (socket destroyed),
 *                              later requests behave normally (forces resume)
 *  GET /file/empty.bin      -> 200 + Content-Length: 1000 but sends ZERO body
 *                              bytes then ends (truncation-detection test)
 *
 * Every request is logged (stdout line + JSONL file) with:
 *   seq, ts, method, path, range_header, status, content_range,
 *   content_length_header, bytes_written, cut, remote_port, user_agent
 *
 * Standalone:
 *   node fixture-server.js [--port 8787] [--log fixture-requests.jsonl]
 * Module:
 *   const { createServer, makeBytes, SIZE, ... } = require('./fixture-server.js');
 */

const http = require('http');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const SIZE = 8 * 1024 * 1024;          // 8388608 bytes: plain.bin, norange.bin, flaky.bin
const BASE_SEED = 0x1234abcd;          // 305419917
const PARTIAL_SIZE = 3145728;          // 3 MiB pre-existing partial for resume scenarios
const FLAKY_CUT = 4 * 1024 * 1024;     // 4194304 bytes the flaky server delivers, then cuts
const EMPTY_DECLARED = 1000;           // empty.bin declares Content-Length: 1000
const DEFAULT_PORT = 8787;
const DEFAULT_LOG = path.join(process.cwd(), 'fixture-requests.jsonl');

function fnv1a32(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i) & 0xff;
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

function seedFor(name) {
  return (BASE_SEED ^ fnv1a32(name)) >>> 0;
}

/** Generate the deterministic buffer for one logical file name. */
function makeBytes(name, length) {
  const buf = Buffer.allocUnsafe(length);
  let x = seedFor(name) >>> 0;
  for (let i = 0; i < length; i++) {
    x ^= (x << 13) >>> 0;
    x >>>= 0;
    x ^= x >>> 17;
    x ^= (x << 5) >>> 0;
    x >>>= 0;
    buf[i] = x & 0xff;
  }
  return buf;
}

const FILES = {
  'plain.bin': { size: SIZE, supportsRange: true, cutFirstRequest: false },
  'norange.bin': { size: SIZE, supportsRange: false, cutFirstRequest: false },
  'flaky.bin': { size: SIZE, supportsRange: true, cutFirstRequest: true },
  'empty.bin': { size: EMPTY_DECLARED, supportsRange: false, cutFirstRequest: false, sendNoBody: true },
};

// Precompute content once (4 x 8 MiB worst case ~ 32 MiB).
const CONTENT = {};
for (const name of Object.keys(FILES)) {
  CONTENT[name] = makeBytes(name, FILES[name].size);
}

function sha256(buf) {
  return crypto.createHash('sha256').update(buf).digest('hex');
}

/** Parse a single-range "bytes=start-end" header. Returns null if unparsable. */
function parseRange(header, size) {
  if (typeof header !== 'string') return null;
  const m = /^bytes=(\d*)-(\d*)$/.exec(header.trim());
  if (!m) return null;
  let start;
  let end;
  if (m[1] === '' && m[2] === '') return null;
  if (m[1] === '') {
    // suffix range: last N bytes
    const n = parseInt(m[2], 10);
    if (!Number.isFinite(n) || n <= 0) return null;
    start = Math.max(0, size - n);
    end = size - 1;
  } else {
    start = parseInt(m[1], 10);
    end = m[2] === '' ? size - 1 : parseInt(m[2], 10);
  }
  if (!Number.isFinite(start) || !Number.isFinite(end)) return null;
  if (start > end || start >= size) return { unsatisfiable: true, start, end };
  return { start, end: Math.min(end, size - 1) };
}

/**
 * Create the fixture HTTP server.
 * @param {object} [opts]
 * @param {string|null} [opts.logPath] JSONL request log path (null = memory only)
 * @param {(rec:object)=>void} [opts.onRequest] live callback for each request record
 * @param {boolean} [opts.quiet] suppress stdout request lines
 */
function createServer(opts) {
  opts = opts || {};
  const logPath = opts.logPath === undefined ? null : opts.logPath;
  const onRequest = typeof opts.onRequest === 'function' ? opts.onRequest : null;
  const quiet = !!opts.quiet;
  const records = [];
  const counters = { seq: 0, flakyRequests: 0 };

  const server = http.createServer(function (req, res) {
    const started = Date.now();
    const url = new URL(req.url, 'http://' + (req.headers.host || '127.0.0.1'));
    const pathname = url.pathname;
    // Optional throttle: ?rate=<bytes/sec> streams the body at that rate so a
    // lifecycle test has time to kill / idle / cut the network mid-transfer.
    // 0 or absent = send immediately (default; deterministic timing).
    let rate = parseInt(url.searchParams.get('rate') || '0', 10);
    if (!Number.isFinite(rate) || rate < 0) rate = 0;
    if (rate > 50 * 1024 * 1024) rate = 50 * 1024 * 1024;
    const rec = {
      seq: ++counters.seq,
      ts: new Date().toISOString(),
      method: req.method,
      path: pathname,
      raw_url: req.url,
      range_header: req.headers.range || null,
      status: null,
      content_range: null,
      content_length_header: null,
      bytes_written: 0,
      cut: false,
      remote_port: req.socket ? req.socket.remotePort : null,
      user_agent: req.headers['user-agent'] || null,
      duration_ms: null,
    };

    function finish(extra) {
      if (rec.__done) return;   // guard: 'finish' and 'close' can both fire
      rec.__done = true;
      if (extra) Object.assign(rec, extra);
      rec.duration_ms = Date.now() - started;
      records.push(rec);
      if (logPath) {
        try { fs.appendFileSync(logPath, JSON.stringify(rec) + '\n'); } catch (e) { /* ignore */ }
      }
      if (onRequest) { try { onRequest(rec); } catch (e) { /* ignore */ } }
      if (!quiet) {
        const line = '[fixture] #' + rec.seq + ' ' + rec.method + ' ' + rec.path +
          ' range=' + (rec.range_header || '-') + ' status=' + rec.status +
          ' cr=' + (rec.content_range || '-') + ' bytes=' + rec.bytes_written +
          (rec.cut ? ' CUT' : '');
        process.stdout.write(line + '\n');
      }
    }

    if (req.method !== 'GET') {
      rec.status = 405;
      res.writeHead(405, { 'Content-Type': 'text/plain', 'Allow': 'GET' });
      res.end('method not allowed');
      finish();
      return;
    }

    if (pathname === '/health') {
      const body = Buffer.from(JSON.stringify(health(), null, 2));
      rec.status = 200;
      rec.content_length_header = body.length;
      res.writeHead(200, { 'Content-Type': 'application/json', 'Content-Length': body.length });
      res.end(body);
      finish();
      return;
    }

    if (!pathname.startsWith('/file/')) {
      rec.status = 404;
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('not found');
      finish();
      return;
    }

    const name = pathname.slice('/file/'.length);
    const meta = FILES[name];
    if (!meta) {
      rec.status = 404;
      res.writeHead(404, { 'Content-Type': 'text/plain' });
      res.end('unknown fixture: ' + name);
      finish();
      return;
    }

    const buf = CONTENT[name];
    const size = meta.size;

    // empty.bin: advertise 1000 bytes, send nothing, end the response.
    if (meta.sendNoBody) {
      rec.status = 200;
      rec.content_length_header = EMPTY_DECLARED;
      res.writeHead(200, { 'Content-Type': 'application/octet-stream', 'Content-Length': EMPTY_DECLARED });
      res.end();
      finish();
      return;
    }

    const rangeHeader = req.headers.range;
    const parsed = meta.supportsRange ? parseRange(rangeHeader, size) : null;
    const ignoreRange = !meta.supportsRange;

    if (parsed && parsed.unsatisfiable) {
      rec.status = 416;
      rec.content_range = 'bytes */' + size;
      res.writeHead(416, { 'Content-Range': 'bytes */' + size, 'Content-Type': 'text/plain' });
      res.end();
      finish();
      return;
    }

    const useRange = !!parsed;
    const start = useRange ? parsed.start : 0;
    const end = useRange ? parsed.end : size - 1;
    const chunk = buf.subarray(start, end + 1); // zero-copy view

    rec.status = useRange ? 206 : 200;
    rec.content_length_header = chunk.length;
    const headers = {
      'Content-Type': 'application/octet-stream',
      'Content-Length': chunk.length,
      'Accept-Ranges': meta.supportsRange ? 'bytes' : 'none',
      'Cache-Control': 'no-store',
      'X-Fixture-Name': name,
      'X-Fixture-Sha256': sha256(buf),
    };
    if (rate > 0) headers['X-Fixture-Rate'] = String(rate);
    if (useRange) {
      rec.content_range = 'bytes ' + start + '-' + end + '/' + size;
      headers['Content-Range'] = rec.content_range;
    }
    res.writeHead(rec.status, headers);

    const doCut = meta.cutFirstRequest && counters.flakyRequests === 0;
    if (doCut) counters.flakyRequests++;

    if (!doCut) {
      if (rate > 0) {
        // Throttled stream (paced 64 KiB writes) so a lifecycle test can act
        // mid-transfer. Same bytes, same final SHA-256 -- only timing changes.
        const CHUNK = 64 * 1024;
        const intervalMs = Math.max(5, Math.round((CHUNK / rate) * 1000));
        let off = 0;
        rec.rate = rate;
        rec.bytes_written = 0;
        const timer = setInterval(function () {
          if (res.destroyed || res.writableEnded) { clearInterval(timer); return; }
          const part = chunk.subarray(off, Math.min(off + CHUNK, chunk.length));
          off += part.length;
          rec.bytes_written += part.length;
          res.write(part);
          if (off >= chunk.length) { clearInterval(timer); res.end(); }
        }, intervalMs);
        res.on('close', function () {
          clearInterval(timer);
          if (!res.writableEnded && !res.destroyed) { try { res.destroy(); } catch (e) { /* ignore */ } }
          finish();
        });
        res.on('finish', function () { finish(); });
        return;
      }
      rec.bytes_written = chunk.length;
      res.end(chunk, function () { finish(); });
      return;
    }

    // flaky.bin first request: deliver up to FLAKY_CUT bytes, then destroy socket.
    const cutLen = Math.min(FLAKY_CUT, chunk.length);
    const first = chunk.subarray(0, cutLen);
    rec.bytes_written = cutLen;
    rec.cut = true;
    res.write(first, function () {
      // Give the kernel a moment to flush, then hard-close the connection.
      setTimeout(function () {
        try { res.socket.destroy(); } catch (e) { /* ignore */ }
        finish();
      }, 100);
    });
  });

  server.fixture = {
    records,
    reset: function () { records.length = 0; counters.seq = 0; counters.flakyRequests = 0; },
    health: health,
  };
  return server;
}

function health() {
  const files = {};
  for (const name of Object.keys(FILES)) {
    files[name] = {
      size: FILES[name].size,
      supportsRange: FILES[name].supportsRange,
      cutFirstRequest: !!FILES[name].cutFirstRequest,
      sendNoBody: !!FILES[name].sendNoBody,
      seed: seedFor(name),
      sha256_from_server: sha256(CONTENT[name]),
    };
  }
  return {
    ok: true,
    prng: 'xorshift32 seeded by (0x' + BASE_SEED.toString(16) + ' ^ fnv1a32(name))',
    base_seed: BASE_SEED,
    partial_size: PARTIAL_SIZE,
    flaky_cut: FLAKY_CUT,
    throttle_param: 'append ?rate=<bytes/sec> to /file/<name> to stream slowly (same bytes/hashes)',
    files: files,
  };
}

module.exports = {
  createServer,
  makeBytes,
  seedFor,
  sha256,
  health,
  SIZE,
  BASE_SEED,
  PARTIAL_SIZE,
  FLAKY_CUT,
  EMPTY_DECLARED,
  CONTENT,
  FILES,
  DEFAULT_PORT,
  DEFAULT_LOG,
};

if (require.main === module) {
  const argv = process.argv.slice(2);
  let port = DEFAULT_PORT;
  let logPath = DEFAULT_LOG;
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--port') port = parseInt(argv[++i], 10);
    else if (argv[i] === '--log') logPath = argv[++i];
    else if (argv[i] === '--no-log') logPath = null;
  }
  try { fs.writeFileSync(logPath, ''); } catch (e) { /* ignore */ }
  const server = createServer({ logPath: logPath });
  server.listen(port, '127.0.0.1', function () {
    const h = health();
    console.log('fixture-server listening on http://127.0.0.1:' + port);
    console.log('request log: ' + logPath);
    console.log('reference hashes:');
    for (const name of Object.keys(h.files)) {
      const f = h.files[name];
      console.log('  ' + name + ' size=' + f.size + ' sha256=' + f.sha256_from_server);
    }
  });
}
